+public class JettyCoreRequestUpgradeStrategy implements RequestUpgradeStrategy {
+
+	@Nullable
+	private Consumer<Configurable> webSocketConfigurer;
+
+	@Nullable
+	private ServerWebSocketContainer serverContainer;
